import{errorFromJson,errorToJson}from"./error-json.js";import{appendHeaders}from"../http-headers.js";import{ConnectError}from"../connect-error.js";import{Code}from"../code.js";export const endStreamFlag=2;export function endStreamFromJson(data){const parseErr=new ConnectError("invalid end stream",Code.InvalidArgument);let jsonValue;try{jsonValue=JSON.parse("string"==typeof data?data:(new TextDecoder).decode(data))}catch(e){throw parseErr}if("object"!=typeof jsonValue||null==jsonValue||Array.isArray(jsonValue))throw parseErr;const metadata=new Headers;if("metadata"in jsonValue){if("object"!=typeof jsonValue.metadata||null==jsonValue.metadata||Array.isArray(jsonValue.metadata))throw parseErr;for(const[key,values]of Object.entries(jsonValue.metadata)){if(!Array.isArray(values)||values.some((value=>"string"!=typeof value)))throw parseErr;for(const value of values)metadata.append(key,value)}}return{metadata:metadata,error:"error"in jsonValue?errorFromJson(jsonValue.error,metadata,parseErr):void 0}}export function endStreamToJson(metadata,error,jsonWriteOptions){const es={};void 0!==error&&(es.error=errorToJson(error,jsonWriteOptions),metadata=appendHeaders(metadata,error.metadata));let hasMetadata=!1;const md={};return metadata.forEach(((value,key)=>{hasMetadata=!0,md[key]=[value]})),hasMetadata&&(es.metadata=md),es}export function createEndStreamSerialization(options){const textEncoder=new TextEncoder;return{serialize(data){try{const jsonObject=endStreamToJson(data.metadata,data.error,options),jsonString=JSON.stringify(jsonObject);return textEncoder.encode(jsonString)}catch(e){const m=e instanceof Error?e.message:String(e);throw new ConnectError(`failed to serialize EndStreamResponse: ${m}`,Code.Internal)}},parse(data){try{return endStreamFromJson(data)}catch(e){const m=e instanceof Error?e.message:String(e);throw new ConnectError(`failed to parse EndStreamResponse: ${m}`,Code.InvalidArgument)}}}}