import{makeProtoRuntime}from"./private/proto-runtime.js";import{InternalFieldList}from"./private/field-list.js";import{scalarZeroValue}from"./private/scalars.js";import{normalizeFieldInfos}from"./private/field-normalize.js";export const proto3=makeProtoRuntime("proto3",(fields=>new InternalFieldList(fields,(source=>normalizeFieldInfos(source,!0)))),(target=>{for(const member of target.getType().fields.byMember()){if(member.opt)continue;const name=member.localName,t=target;if(member.repeated)t[name]=[];else switch(member.kind){case"oneof":t[name]={case:void 0};break;case"enum":t[name]=0;break;case"map":t[name]={};break;case"scalar":t[name]=scalarZeroValue(member.T,member.L)}}}));