import{useMutation}from"@tanstack/react-query";import{sendTransactionMutationOptions}from"@wagmi/core/query";import{useConfig}from"./useConfig.js";export function useSendTransaction(parameters={}){const{mutation:mutation}=parameters,config=useConfig(parameters),mutationOptions=sendTransactionMutationOptions(config),{mutate:mutate,mutateAsync:mutateAsync,...result}=useMutation({...mutation,...mutationOptions});return{...result,sendTransaction:mutate,sendTransactionAsync:mutateAsync}}