import{simulateContract as viem_simulateContract}from"viem/actions";import{getAction}from"../utils/getAction.js";import{getConnectorClient}from"./getConnectorClient.js";export async function simulateContract(config,parameters){const{abi:abi,chainId:chainId,connector:connector,...rest}=parameters;let account;if(parameters.account)account=parameters.account;else{account=(await getConnectorClient(config,{chainId:chainId,connector:connector})).account}const client=config.getClient({chainId:chainId}),action=getAction(client,viem_simulateContract,"simulateContract"),{result:result,request:request}=await action({...rest,abi:abi,account:account});return{chainId:client.chain.id,result:result,request:{...request,chainId:chainId}}}