import{localOneofName}from"./names.js";import{assert}from"./assert.js";export class InternalOneofInfo{constructor(name){this.kind="oneof",this.repeated=!1,this.packed=!1,this.opt=!1,this.req=!1,this.default=void 0,this.fields=[],this.name=name,this.localName=localOneofName(name)}addField(field){assert(field.oneof===this,`field ${field.name} not one of ${this.name}`),this.fields.push(field)}findField(localName){if(!this._lookup){this._lookup=Object.create(null);for(let i=0;i<this.fields.length;i++)this._lookup[this.fields[i].localName]=this.fields[i]}return this._lookup[localName]}}