import{getTransactionConfirmations as viem_getTransactionConfirmations}from"viem/actions";import{getAction}from"../utils/getAction.js";export function getTransactionConfirmations(config,parameters){const{chainId:chainId,...rest}=parameters,client=config.getClient({chainId:chainId});return getAction(client,viem_getTransactionConfirmations,"getTransactionConfirmations")(rest)}