import{Code}from"../code.js";export function codeToString(value){const name=Code[value];return"string"!=typeof name?value.toString():name[0].toLowerCase()+name.substring(1).replace(/[A-Z]/g,(c=>"_"+c.toLowerCase()))}let stringToCode;export function codeFromString(value){if(!stringToCode){stringToCode={};for(const value of Object.values(Code))"string"!=typeof value&&(stringToCode[codeToString(value)]=value)}return stringToCode[value]}