import{useMutation}from"@tanstack/react-query";import{switchAccountMutationOptions}from"@wagmi/core/query";import{useConfig}from"./useConfig.js";import{useConnections}from"./useConnections.js";export function useSwitchAccount(parameters={}){const{mutation:mutation}=parameters,config=useConfig(parameters),mutationOptions=switchAccountMutationOptions(config),{mutate:mutate,mutateAsync:mutateAsync,...result}=useMutation({...mutation,...mutationOptions});return{...result,connectors:useConnections({config:config}).map((connection=>connection.connector)),switchAccount:mutate,switchAccountAsync:mutateAsync}}