import{callMonitored}from"../monitor";import{computeStackTrace}from"./computeStackTrace";export function createHandlingStack(){const error=new Error;let formattedStack;return callMonitored((()=>{const stackTrace=computeStackTrace(error);stackTrace.stack=stackTrace.stack.slice(2),formattedStack=toStackTraceString(stackTrace)})),formattedStack}export function toStackTraceString(stack){let result=formatErrorMessage(stack);return stack.stack.forEach((frame=>{const func="?"===frame.func?"<anonymous>":frame.func,args=frame.args&&frame.args.length>0?`(${frame.args.join(", ")})`:"",line=frame.line?`:${frame.line}`:"",column=frame.line&&frame.column?`:${frame.column}`:"";result+=`\n  at ${func}${args} @ ${frame.url}${line}${column}`})),result}export function formatErrorMessage(stack){return`${stack.name||"Error"}: ${stack.message}`}