import{getEnsAvatar as viem_getEnsAvatar}from"viem/actions";import{getAction}from"../utils/getAction.js";export function getEnsAvatar(config,parameters){const{chainId:chainId,...rest}=parameters,client=config.getClient({chainId:chainId});return getAction(client,viem_getEnsAvatar,"getEnsAvatar")(rest)}