import{getProof}from"../actions/getProof.js";import{filterQueryOptions}from"./utils.js";export function getProofQueryOptions(config,options={}){return{async queryFn({queryKey:queryKey}){const{address:address,scopeKey:_,storageKeys:storageKeys,...parameters}=queryKey[1];if(!address||!storageKeys)throw new Error("address and storageKeys are required");return getProof(config,{...parameters,address:address,storageKeys:storageKeys})},queryKey:getProofQueryKey(options)}}export function getProofQueryKey(options){return["getProof",filterQueryOptions(options)]}