export function trailerDemux(header){const h=new Headers,t=new Headers;return header.forEach(((value,key)=>{key.toLowerCase().startsWith("trailer-")?t.set(key.substring(8),value):h.set(key,value)})),[h,t]}export function trailerMux(header,trailer){const h=new Headers(header);return trailer.forEach(((value,key)=>{h.set(`trailer-${key}`,value)})),h}