import{BigNumber}from"ethers";function locateArrayPosition(curve,currentRelativeBlock){const relativeBlocks=curve.relativeBlocks;let prev=0,next=0;for(;next<relativeBlocks.length;next++){if(relativeBlocks[next]>=currentRelativeBlock)return[prev,next];prev=next}return[next-1,next-1]}class NonLinearDutchDecayLib{static decay(curve,startAmount,decayStartBlock,currentBlock){if(curve.relativeAmounts.length>16)throw new Error("InvalidDecayCurve");if(decayStartBlock>=currentBlock||0===curve.relativeAmounts.length)return startAmount;const blockDelta=currentBlock-decayStartBlock;if(curve.relativeBlocks[0]>blockDelta)return this.linearDecay(0,curve.relativeBlocks[0],blockDelta,startAmount,startAmount.sub(curve.relativeAmounts[0].toString()));const[prev,next]=locateArrayPosition(curve,blockDelta),lastAmount=startAmount.sub(curve.relativeAmounts[prev].toString()),nextAmount=startAmount.sub(curve.relativeAmounts[next].toString());return this.linearDecay(curve.relativeBlocks[prev],curve.relativeBlocks[next],blockDelta,lastAmount,nextAmount)}static linearDecay(startPoint,endPoint,currentPoint,startAmount,endAmount){if(currentPoint>=endPoint)return endAmount;const elapsed=BigNumber.from(currentPoint-startPoint),duration=BigNumber.from(endPoint-startPoint);let delta;return delta=endAmount.lt(startAmount)?BigNumber.from(0).sub(startAmount.sub(endAmount).mul(elapsed).div(duration)):endAmount.sub(startAmount).mul(elapsed).div(duration),startAmount.add(delta)}}export{NonLinearDutchDecayLib};export function getBlockDecayedAmount(config,atBlock){const{decayStartBlock:decayStartBlock,startAmount:startAmount,relativeBlocks:relativeBlocks,relativeAmounts:relativeAmounts}=config;return NonLinearDutchDecayLib.decay({relativeAmounts:relativeAmounts,relativeBlocks:relativeBlocks},startAmount,decayStartBlock,atBlock)}export function getEndAmount(config){const{startAmount:startAmount,relativeAmounts:relativeAmounts}=config;if(!startAmount||!relativeAmounts)throw new Error("Invalid config for getting V3 decay end amount");return startAmount.sub(relativeAmounts[relativeAmounts.length-1].toString())}